// Validate incoming payload
const body = $input.first().json.body || $input.first().json;

if (!body.repository || !body.source_branch || !body.target_branch) {
  throw new Error('Missing required fields: repository, source_branch, or target_branch');
}

const parts = body.repository.split('/');
if (parts.length !== 2) {
  throw new Error('Repository must be formatted as owner/repo');
}

return [{
  json: {
    owner: parts[0],
    repo: parts[1],
    repository: body.repository,
    source_branch: body.source_branch,
    target_branch: body.target_branch,
    ai_review: body.ai_review !== false,
    telegram: body.telegram === true
  }
}];

const existing = $input.first().json;
const inputData = $('Validate Input').first().json;

return [{
  json: {
    ...inputData,
    pr_number: existing.number,
    pr_url: existing.html_url,
    pr_exists: true,
    pr_created: false
  }
}];

const created = $input.first().json;
const inputData = $('Validate Input').first().json;

return [{
  json: {
    ...inputData,
    pr_number: created.number,
    pr_url: created.html_url,
    pr_exists: false,
    pr_created: true
  }
}];

const files = $input.all().map(i => i.json);
const prData = $('PR Exists?').first().json.id !== undefined ? $('Use Existing PR').first().json : $('Normalize Created PR').first().json;

let diffSummary = files.map(f => `File: ${f.filename} (${f.status})
Additions: ${f.additions}, Deletions: ${f.deletions}
Diff:
${f.patch || '(Binary or empty)'}`).join('\n\n---\n\n');

// Truncate to avoid context window overflows if diff is huge
if (diffSummary.length > 25000) {
  diffSummary = diffSummary.substring(0, 25000) + '\n\n...[diff truncated for length]...';
}

return [{
  json: {
    ...prData,
    file_count: files.length,
    diff_summary: diffSummary
  }
}];

