const aiEnabled = base.ai_review;
const tgEnabled = base.telegram;

return [{
  json: {
    success: true,
    pr_exists: base.pr_exists,
    pr_created: base.pr_created,
    pr_number: base.pr_number,
    repository: base.repository,
    source_branch: base.source_branch,
    target_branch: base.target_branch,
    review_completed: aiEnabled,
    comment_posted: aiEnabled,
    telegram_sent: tgEnabled,
    pr_url: base.pr_url
  }
}];
